const icon=n=>`<svg class="icon lucide icon-${n}" aria-hidden="true" viewBox="0 0 24 24">${paths[n]||paths.layers}</svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon))}
const btn=(label,cls='',attrs='')=>`<button class="button ${cls}" ${attrs}>${label}</button>`;
const badge=(label,cls='')=>`<span class="badge ${cls}">${label}</span>`;
const components=[];
const add=(name,category,variants,description,html,tokens)=>components.push({name,category,variants,description,html,tokens:tokens||['--radius-control','--surface','--text','--border','--accent']});
add('Button','Action','5 variants','Actions with a clear hierarchy. Use one primary action per region, secondary for alternatives, and ghost for low emphasis.',`<div class="row">${btn('Get started '+icon('arrow'),'primary','data-notify="You’re ready to get started."')}${btn('Secondary','secondary','data-notify="Secondary action selected."')}</div><div class="row">${btn('Ghost','ghost','data-notify="Ghost action selected."')}${btn('Delete','danger','data-notify="Delete button preview. No data was removed."')}${btn('Disabled','','disabled')}</div>`);
add('Icon button','Action','3 states','Compact actions with accessible names. Toggle buttons expose pressed state, and disabled actions remain visible.',`<div class="row">${['plus','heart','star','link','more'].map((n,i)=>`<button class="icon-button" aria-label="${['Add item','Favorite','Bookmark','Copy link','More options'][i]}" ${i===1?'aria-pressed="true"':i===2?'aria-pressed="false"':i===0?'data-notify="Item added."':i===3?'data-copy-link':''} ${i===4?'data-notify="More options button preview."':''}>${icon(n)}</button>`).join('')}</div><div class="row"><span class="label-caption">Default</span><span class="label-caption">·</span><span class="label-caption">Selected</span><span class="label-caption">·</span><button class="icon-button" aria-label="Disabled add" disabled>${icon('plus')}</button></div>`);
add('Segmented control','Action','2 layouts','Switch between mutually exclusive views. Each control exposes its selected state and supports arrow-key navigation.',`<div class="segmented" data-segment role="group" aria-label="Display mode">${['Grid','List','Board'].map((x,i)=>`<button class="${i===0?'active':''}" aria-pressed="${i===0}">${icon(['grid','list','layout'][i])}${x}</button>`).join('')}</div><div class="segmented" data-segment role="group" aria-label="Billing interval"><button class="active" aria-pressed="true">Monthly</button><button aria-pressed="false">Yearly ${badge('−20%','green')}</button></div>`);
add('Text input','Form controls','3 states','Labeled fields with persistent hints and associated validation messages. Error meaning is communicated with text as well as color.',`<label class="field">Email address<div class="input-shell">${icon('mail')}<input type="email" placeholder="you@studio.com" aria-label="Email address"></div></label><label class="field">Workspace URL<input value="orbit studio" class="invalid" aria-invalid="true" aria-describedby="url-error"><span class="error" id="url-error">Use letters, numbers, and hyphens only.</span></label>`);
add('Switch','Form controls','On / off','Turn a setting on or off immediately. Each switch has a descriptive label and a generous interaction area.',`<div class="stack"><div class="switch-row"><div>Email notifications<p>The important things, in your inbox.</p></div><label class="switch"><input type="checkbox" role="switch" aria-label="Email notifications" checked><span></span></label></div><div class="switch-row"><div>Weekly digest<p>A small recap of your week.</p></div><label class="switch"><input type="checkbox" role="switch" aria-label="Weekly digest"><span></span></label></div><div class="switch-row"><span class="muted">Product updates</span><label class="switch"><input type="checkbox" role="switch" aria-label="Product updates" disabled><span></span></label></div></div>`);
add('Checkbox & radio','Form controls','2 controls','Use checkboxes for independent choices and radio buttons for a single selection within a set.',`<div class="stack"><label class="choice"><input type="checkbox" checked>Include all team members</label><label class="choice"><input type="checkbox">Send a copy to myself</label><div style="height:1px;background:var(--border);margin:2px 0"></div><div class="row" style="gap:24px"><label class="choice"><input type="radio" name="access" checked>Everyone</label><label class="choice"><input type="radio" name="access">Only me</label></div></div>`);
add('Badge & status','Feedback & status','5 variants','Quiet status indicators with semantic text colors. A dot, label, or sign carries the meaning beyond color.',`<div class="row">${badge('<span class="status-dot"></span> Active','green')}${badge('Pending','amber')}${badge('Inactive')}${badge('New','purple')}</div><div class="row">${badge('+24.8%','green')}${badge('−12.3%','red')}${badge('0%')}${badge('Pro','purple')}</div>`,['--green-a1','--success-text','--red-a1','--danger-text','--accent-text']);
add('Metric & sparkline','Data display','2 metrics','A compact metric, comparison, and trend. A lavender line and restrained gradient highlight the trend.',`<div class="mini-stats"><div class="stat"><span>People <span class="status-dot" style="background:var(--accent)"></span></span><strong>2,369</strong>${badge('+18.6%','green')}</div><div class="stat"><span>Revenue</span><strong>$750</strong>${badge('+32.1%','green')}</div></div><svg class="chart" viewBox="0 0 300 70" preserveAspectRatio="none" role="img" aria-label="People increased over the last seven days"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#918df6" stop-opacity=".17"/><stop offset="1" stop-color="#918df6" stop-opacity="0"/></linearGradient></defs><path d="M0 55C20 20 35 47 60 39S95 53 120 34 150 42 175 24 200 40 230 16 267 32 300 5V70H0Z" fill="url(#area)"/><path d="M0 55C20 20 35 47 60 39S95 53 120 34 150 42 175 24 200 40 230 16 267 32 300 5" fill="none" stroke="var(--accent)" stroke-width="2.5"/></svg><div class="chart-labels"><span>Sep 4</span><span>Sep 10</span></div>`,['--purple-4','--green-a1','--success-text','--fg-3']);
add('Floating navigation','Navigation','6 destinations','A compact dark navigation dock. Selected destinations have a distinct filled state and an accessible pressed label.',`<div class="dock" role="group" aria-label="Product navigation" data-dock>${['chart','smile','gauge','funnel','settings','globe'].map((x,i)=>`<button class="${!i?'active':''}" aria-pressed="${!i}" aria-label="${['Overview','People','Performance','Funnels','Settings','Realtime'][i]}">${icon(x)}</button>`).join('')}</div><span class="dock-label">Overview</span>`,['--background','--bg-4','--purple-4','--radius-control']);
add('Avatar & group','Content','3 sizes','Abstract color avatars provide recognizable identity without depending on photography. Groups show overflow as a count.',`<div class="row" style="gap:16px;align-items:end"><span class="avatar tiny" role="img" aria-label="Alex avatar"></span><span class="avatar blue" role="img" aria-label="Jamie avatar"></span><span class="avatar mint" style="width:49px;height:49px" role="img" aria-label="Sam avatar"></span></div><div class="row" style="gap:16px"><div class="avatars"><span class="avatar" role="img" aria-label="Alex"></span><span class="avatar blue" role="img" aria-label="Jamie"></span><span class="avatar mint" role="img" aria-label="Sam"></span><span class="avatar-count">+4</span></div><span class="label-caption">Your team, together</span></div>`);
add('Select & date','Form controls','Shared dropdown / calendar','A workspace selector and calendar share the same floating surface, selection colors, and Lucide icons. The calendar supports arrow keys, Home/End, Page Up/Down, Enter, and Escape.',`<div class="field"><span>Workspace</span><div class="dropdown ds-select"><button class="control-trigger" data-select-toggle aria-label="Workspace" aria-haspopup="listbox" aria-expanded="false"><span data-select-label>Personal workspace</span>${icon('down')}</button><div class="dropdown-panel control-panel" role="listbox" aria-label="Workspaces" hidden>${['Personal workspace','Design studio','Product team'].map((n,i)=>`<button type="button" role="option" aria-selected="${!i}" data-option="${n}">${icon(['smile','palette','layers'][i])}<span>${n}</span><span class="option-check">${icon('check')}</span></button>`).join('')}</div></div></div><div class="field"><span>Start date</span><div class="dropdown ds-date" data-date="2026-09-10"><button class="control-trigger" data-date-toggle aria-label="Start date" aria-haspopup="dialog" aria-expanded="false"><span data-date-label>Sep 10, 2026</span>${icon('calendar')}</button><div class="calendar-panel control-panel" role="dialog" aria-label="Choose start date" hidden></div></div></div>`);
add('Progress & score','Feedback & status','2 patterns','A progress ring pairs a numerical score with a written evaluation. Linear progress shows a measurable completion value.',`<div class="row" style="gap:18px"><div class="ring" role="img" aria-label="Experience score: 95 out of 100"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="34"/><circle cx="40" cy="40" r="34"/></svg><strong>95</strong></div><div class="performance-copy"><h3>Excellent</h3><p>A little care makes a big difference.</p></div></div><div class="stack" style="gap:7px"><div class="row spread label-caption"><span>Storage used</span><span>68%</span></div><div class="progress" role="progressbar" aria-label="Storage used" aria-valuenow="68" aria-valuemin="0" aria-valuemax="100"><span></span></div></div>`,['--green-4','--green-a1','--accent','--bg-3']);
add('Dropdown menu','Action','3 actions','A contextual action list that opens on demand, dismisses on Escape or outside click, and supports keyboard navigation.',`<div class="dropdown">${btn('Project actions '+icon('down'),'','data-menu-toggle aria-expanded="false" aria-haspopup="true"')}<div class="dropdown-panel" hidden><button data-notify="Project renamed in this preview.">${icon('edit')}Rename project</button><button data-notify="Project duplicated.">${icon('copy')}Duplicate</button><hr><button data-notify="Archive action preview. No project was changed.">${icon('folder')}Archive project</button></div></div><span class="label-caption">A place for the secondary things</span>`);
add('Tabs','Navigation','3 tabs','Switch related content in place. Tabs expose selected state, are connected to their panels, and support arrow keys.',`<div class="tabs" role="tablist" aria-label="Project settings">${['Overview','Activity','Settings'].map((x,i)=>`<button role="tab" aria-selected="${!i}" tabindex="${i?-1:0}" class="${!i?'active':''}" data-tab="${x}">${x}</button>`).join('')}</div><div class="tab-panel" role="tabpanel">Everything in one place.<br>Your project is up to date and ready to go.</div>`);
add('Banner','Feedback & status','2 sentiments','Inline feedback communicates what happened and whether the user needs to act. Text remains readable in both themes.',`<div class="banner">${icon('circlecheck')}<div>All changes saved<p>You’re right where you left off.</p></div></div><div class="banner info">${icon('info')}<div>A little heads-up<p>Your trial ends in 3 days.</p></div></div>`);
add('Table','Table & list','3 rows','Compact rows with subtle filled backgrounds. Semantic column headers keep the values understandable to screen readers.',`<table class="table"><caption class="sr-only">Traffic sources and people</caption><thead><tr><th scope="col">Source</th><th scope="col">People</th><th scope="col">Change</th></tr></thead><tbody>${[['Direct','1,310','+24%'],['Search','457','+18%'],['Social','273','−6%']].map((r,i)=>`<tr><td>${icon(['arrow','search','globe'][i])}${r[0]}</td><td>${r[1]}</td><td>${badge(r[2],i===2?'red':'green')}</td></tr>`).join('')}</tbody></table>`);
add('Card','Container','Project pattern','A composed container for a project summary. Surface, border, and spacing tokens work independently of product domain.',`<div class="mini-card"><div class="row spread"><span class="avatar blue tiny" aria-hidden="true"></span>${badge('In progress','purple')}</div><h3 style="margin-top:12px">Something worth making</h3><p>A home for your next big idea.</p>${btn('Open project '+icon('arrow'),'small','data-open-project')}</div>`);
add('Slider','Form controls','Interactive','Choose a value along a range. The live output is associated with the labeled slider and updates on every change.',`<div class="stack"><label class="field">Monthly events<div class="row spread"><span style="font-size:25px"> <output data-range-value>10,000</output></span>${badge('Starter','purple')}</div><input type="range" class="range" min="1000" max="50000" value="10000" step="100" aria-label="Monthly events"><div class="row spread label-caption"><span>1,000</span><span>50,000</span></div></label></div>`);
add('Dialog','Overlay','Interactive','A focused modal for a single task. Native dialog manages focus containment and Escape. The form validates before confirming.',`<div class="empty-icon">${icon('layers')}</div>${btn('Create a project '+icon('plus'),'','data-open-project')}<span class="label-caption">A little space for a new idea</span>`);
add('Toast','Overlay','Interactive','Transient confirmation after an action. The message is announced through a live status region without moving focus.',`<div class="toast-preview">${icon('circlecheck')}<span>Changes saved successfully</span><span class="muted" style="margin-left:auto">just now</span></div>${btn('Show toast','small','data-notify="Changes saved successfully."')}`);
add('Tooltip','Overlay','Hover / focus','A short label for an icon action, shown on pointer hover and keyboard focus. It never contains essential instructions.',`<div class="row" style="gap:20px">${['copy','download','heart'].map((x,i)=>`<div class="tooltip-wrap"><button class="icon-button" aria-label="${['Copy component','Download tokens','Favorite component'][i]}" ${i===2?'aria-pressed="false"':`data-notify="${i?'Download button preview. Use Export tokens for the full palette.':'Component copied in this preview.'}"`}>${icon(x)}</button><span class="tooltip" role="tooltip">${['Copy component','Download tokens','Add to favorites'][i]}</span></div>`).join('')}</div><span class="label-caption">Hover or focus to take a peek</span>`);
add('Pagination','Navigation','5 pages','Navigate a bounded set of pages. Current page and visible item range stay synchronized, including previous and next actions.',`<div class="pagination" aria-label="Result pages"><button data-page="prev" aria-label="Previous page" disabled>${icon('chevron')}</button>${[1,2,3,4,5].map(i=>`<button data-page="${i}" ${i===1?'class="active" aria-current="page"':''} aria-label="Page ${i}">${i}</button>`).join('')}<button data-page="next" aria-label="Next page">${icon('chevron')}</button></div><span class="label-caption page-range">Showing 1–10 of 50 items</span>`);
add('Stepper','Navigation','3 steps','Progress through a short sequence with completed, current, and upcoming steps. The demo advances and can be restarted.',`<div class="stepper"><div class="step done"><span>${icon('check')}</span>Account</div><i class="step-line"></i><div class="step current"><span>2</span>Details</div><i class="step-line"></i><div class="step"><span>3</span>Finish</div></div>${btn('Continue '+icon('arrow'),'small','data-step-next')}`);
add('Empty state','Content','Actionable','Explain what belongs in an empty space and offer the next useful action.',`<div class="empty-sample stack" style="align-items:center"><div class="empty-icon">${icon('folder')}</div><h3>A fresh start</h3><p>Your projects will feel at home here.</p>${btn(icon('plus')+' Create project','small','data-open-project')}</div>`);
add('Activity list','Table & list','3 events','A simple timeline pairs an event, context, and time. The connecting line is decorative; event order is semantic.',`<ol class="activity" style="list-style:none;padding:0;margin:0"><li class="activity-item"><span class="activity-symbol">${icon('check')}</span><div>Project published<p>Everything is looking good.</p></div><time>2m ago</time></li><li class="activity-item"><span class="activity-symbol">${icon('smile')}</span><div>Jamie joined the team<p>A little more company.</p></div><time>1h ago</time></li><li class="activity-item"><span class="activity-symbol">${icon('plus')}</span><div>Project created<p>The start of something.</p></div><time>3h ago</time></li></ol>`);
add('Skeleton & spinner','Feedback & status','2 patterns','Static skeletons reserve the shape of loading content. The spinner respects reduced-motion preferences.',`<div class="row" style="width:100%;gap:12px" aria-hidden="true"><div class="skeleton circle"></div><div class="skeleton-lines"><div class="skeleton" style="width:65%"></div><div class="skeleton" style="width:90%"></div></div></div><div class="stack" style="gap:8px" aria-hidden="true"><div class="skeleton"></div><div class="skeleton" style="width:80%"></div></div><div class="row"><span class="spinner" aria-hidden="true"></span><span class="label-caption" role="status">Getting things ready…</span></div>`);
add('Accordion','Container','2 items','Progressively disclose supporting details. Native details elements retain keyboard and screen-reader behavior.',`<div class="stack" style="gap:0"><details open><summary>Made for any product ${icon('chevron')}</summary><p>Use the same building blocks for your next dashboard, workspace, or big idea.</p></details><details><summary>Light and dark, together ${icon('chevron')}</summary><p>Every component shares semantic tokens that adapt to the active theme.</p></details></div>`);
add('Funnel','Data display','3 stages','A flowing stage comparison, with stage names and values available as text.',`<svg class="funnel" viewBox="0 0 300 100" preserveAspectRatio="none" role="img" aria-label="Funnel: 1,979 visitors, 273 signups, 58 subscribers"><path d="M0 7H30C75 7 76 38 115 38H160C200 38 210 45 245 45H300V55H245C210 55 200 62 160 62H115C76 62 75 93 30 93H0Z" fill="var(--purple-a2)" stroke="var(--purple-a1)" stroke-width="8"/><path d="M0 12H30C75 12 76 41 115 41V59C76 59 75 88 30 88H0Z" fill="var(--purple-4)"/><path d="M115 41H160C200 41 210 47 245 47V53C210 53 200 59 160 59H115Z" fill="var(--sky-4)"/><path d="M245 47H300V53H245Z" fill="var(--blue-4)"/></svg><div class="row spread"><div class="stat"><span>Visitors</span><span>1,979</span></div><div class="stat"><span>Signups</span><span>273</span></div><div class="stat"><span>Subscribers</span><span>58</span></div></div>`,['--purple-4','--purple-a2','--sky-4','--blue-4']);
add('Filter chips','Form controls','Removable','Applied filters are visible and individually removable. Clear all and reset keep the example repeatable.',`<div class="row" data-chip-list>${['Active','Design','This month'].map(x=>`<span class="chip">${x}<button aria-label="Remove ${x} filter" data-remove-chip>${icon('x')}</button></span>`).join('')}</div><div class="row">${btn('Clear all','ghost small','data-clear-chips')}${btn('Reset filters','small','data-reset-chips')}</div>`);
add('Chat composer','Chat','Interactive','A simple message field and send action. Messages are kept locally in this demo and announced when added.',`<div class="stack" data-messages aria-live="polite"><div class="message">A place to think things through.</div><div class="message sent">Let’s make something good.</div></div><form class="composer"><input placeholder="Write a message…" aria-label="Write a message" required maxlength="300"><button class="icon-button" aria-label="Send message">${icon('send')}</button></form>`);
add('File input','Form controls','Drop zone / asset picker','An empty-state pattern for assets: drop files on the surface or use Select assets. Selection stays on your device.',`<div class="file-drop asset-drop" role="group" aria-label="Project assets" data-drop-zone><span class="empty-icon">${icon('folder')}</span><strong>A home for your assets</strong><p>Drop a file here to get started.</p><div class="file-actions">${btn(icon('plus')+' Select assets','small secondary','type="button" data-select-assets')}${btn(icon('x'),'small secondary file-remove','type="button" data-remove-asset hidden aria-label="Remove selected file"')}</div><input type="file" hidden tabindex="-1" aria-label="Project attachment"><p data-file-status role="status">No assets selected</p></div>`);
add('Text area','Form controls','Character count','A multiline field with an associated character counter. Length limits are enforced by the native textarea.',`<label class="field">Project description<textarea rows="3" placeholder="What are you working on?" maxlength="200" aria-describedby="text-count"></textarea><span class="hint" id="text-count" data-text-count>0 / 200 characters</span></label>`);
add('Session card','Container','Expandable','A layered activity card. Expand the purchase row to reveal transaction details; spacing and shadows keep nested surfaces quiet.',`<div class="session-card"><p class="session-heading">Session lasted for <span style="color:var(--text)">26s</span></p><details><summary>${icon('circlecheck')} Subscribed <span class="amount">$714</span>${icon('chevron')}</summary><p>Pro plan <span style="float:right">$500.00</span><br><br>Payment received on September 10.<br>One more step in their journey.</p></details><div class="session-row">${icon('gauge')} / <span>968ms</span></div><div class="session-footer">${icon('arrow')} Direct ${icon('globe')}<time>12:25 PM</time></div></div>`);
add('Selection toolbar','Action','Contextual','A compact body toolbar responds to selection. Actions confirm the selected items locally and clear selection after archiving.',`<div class="toolbar-example"><label class="choice"><input type="checkbox" data-toolbar-choice checked> Brand assets</label><label class="choice"><input type="checkbox" data-toolbar-choice checked> Website exploration</label><div class="body-toolbar" aria-label="Selection actions" role="toolbar"><span class="toolbar-count" aria-live="polite">2 selected</span><button class="icon-button" aria-label="Copy selected items" data-toolbar-action="copy">${icon('copy')}</button><span class="toolbar-separator"></span>${btn('Archive','small','data-toolbar-action="archive"')}</div></div>`);
add('Expandable dock','Navigation','Compact / expanded','A floating toolbar opens into a contextual summary. Select Realtime to expand; any other destination collapses it.',`<div class="expanded-dock"><div class="dock-content" aria-hidden="true" inert><div><div class="dock-summary"><span>Pages</span><span class="dock-bar">/</span><small>45</small></div><div class="dock-summary"><span>Referrers</span><span class="dock-bar">${icon('arrow')} Direct</span><small>36</small></div><div class="dock-summary"><span>Countries</span><span class="dock-bar">${icon('globe')} India</span><small>10</small></div></div></div><div class="dock" data-dock role="group" aria-label="Expandable product navigation">${['chart','smile','gauge','funnel','settings','globe'].map((x,i)=>`<button class="${!i?'active':''}" aria-pressed="${!i}" aria-label="${['Overview','People','Performance','Funnels','Settings','Realtime'][i]}" ${i===5?'aria-expanded="false"':''}>${icon(x)}</button>`).join('')}</div><span class="dock-label sr-only">Overview</span></div><span class="label-caption">Select the globe to open the summary</span>`);
add('Attribution table','Table & list','Live / hover / focus','Proportional traffic and revenue segments sit behind stable, borderless rows. Values roll during live updates. Hover or focus a country to reveal revenue, or use Show revenue on touch devices. Pause stops the three-second demo updates.',`<div class="attribution" data-attribution data-playing="true"><div class="attribution-top"><div class="segmented" data-segment role="group" aria-label="Attribution dimension"><button class="active" aria-pressed="true" data-dimension="countries">Countries</button><button aria-pressed="false" data-dimension="sources">Sources</button></div><span data-table-time>Live preview</span></div><table class="ranked-table"><caption class="sr-only">People and revenue by source. Focus a row to show revenue.</caption><thead class="sr-only"><tr><th scope="col">Source</th><th scope="col">People or revenue</th></tr></thead><tbody></tbody></table><div class="attribution-bottom"><span class="attribution-key"><span class="key-block"></span>People <span class="key-block green"></span>Revenue</span><div class="row">${btn('Show revenue','ghost small','data-table-metric')}${btn('Update','small','data-table-update')}${btn('Pause','small','data-table-play aria-pressed="true" aria-label="Automatic table updates"')}</div></div></div>`);
add('Rolling number','Data display','Build / increase / decrease','Individual digits roll inside fixed-width masks. Thousands separators and currency stay legible; the final number is exposed as one accessible label. Try crossing a digit boundary or changing direction.',`<div class="number-demo" data-number-demo><span data-number="2369">2,369</span><span class="label-caption">People, and counting</span><div class="row">${btn('−89','','data-number-action="decrease"')}${btn('+127','primary','data-number-action="increase"')}${btn('Reset','ghost','data-number-action="reset"')}</div><span class="sr-only" role="status"></span></div>`);
add('Visitor table','Table & list','Identity / source / revenue','A compact visitor list with overlapping avatar and country flag, source pills, right-aligned revenue, and quiet timestamps. Value animations share the same numeric primitive as the attribution table.',`<table class="visitor-table"><caption class="sr-only">Visitor activity</caption><thead class="sr-only"><tr><th scope="col">Visitor</th><th scope="col">Source</th><th scope="col">Revenue</th><th scope="col">Last seen</th></tr></thead><tbody>${[['Olivia Patel','🇮🇳','Direct',199,'now'],['Speedy Rabbit','🇧🇷','Community',0,'2m'],['Sarah Mitchell','🇺🇸','Search',249,'5m'],['Quirky Penguin','🇬🇧','Direct',0,'12m'],['James Chen','🇨🇦','Social',99,'1h'],['Fluffy Koala','🇩🇪','Referral',0,'3h']].map((r,i)=>`<tr><td><span class="visitor-name"><span class="visitor-avatar"><span class="avatar ${['','blue','mint'][i%3]}"></span><span class="visitor-flag" aria-label="Country">${r[1]}</span></span><span>${r[0]}</span>${r[3]?`<span class="verified" aria-label="Verified">${icon('circlecheck')}</span>`:''}</span></td><td><span class="referrer-pill">${icon(r[2]==='Direct'?'arrow':'globe')}${r[2]}</span></td><td style="${!r[3]?'color:var(--muted)':''}"><span data-number="${r[3]}" data-format="currency">$${r[3]}</span></td><td>${r[4]}</td></tr>`).join('')}</tbody></table>`);
components.unshift(...components.splice(-3));
const categoryIcons={'Action':'cursor','Form controls':'sliders','Feedback & status':'bell','Navigation':'layout','Data display':'chart','Content':'type','Container':'layers','Overlay':'copy','Table & list':'list','Chat':'chat'};
let view='gallery',category='All components',query='',selectedComponent=null,detailTab='preview',toastTimer;
const $=s=>document.querySelector(s);
function showToast(message){clearTimeout(toastTimer);$('#toast').innerHTML=icon('circlecheck')+'<span></span>';$('#toast span').textContent=message;OrbitMotion.visibility($('#toast'),true);toastTimer=setTimeout(()=>OrbitMotion.visibility($('#toast'),false),3800)}
function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('orbit-theme',theme)}catch{}document.querySelectorAll('[data-theme-choice]').forEach(b=>{b.classList.toggle('active',b.dataset.themeChoice===theme);b.setAttribute('aria-pressed',b.dataset.themeChoice===theme)});if(view==='foundations')renderFoundations()}
function renderNav(){if(window.OrbitEmbed)return;const counts=Object.keys(categoryIcons);$('#categories').innerHTML=counts.map(c=>`<button class="nav-item ${category===c?'selected':''}" data-category="${c}">${icon(categoryIcons[c])}${c}<span class="count">${components.filter(x=>x.category===c).length}</span></button>`).join('');$('#nav-total').textContent=components.length;$('#total').textContent=components.length;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view&&(view==='foundations'||category==='All components');b.classList.toggle(b.classList.contains('nav-item')?'selected':'active',active)})}
function prepareDemo(root){window.OrbitExtras?.prepare(root);window.OrbitStarter?.prepare(root);window.OrbitControls?.prepare(root);root.querySelectorAll("svg [id]").forEach(el=>{const old=el.id;el.id="svg-"+Math.random().toString(36).slice(2,10);el.closest("svg").querySelectorAll("[fill]").forEach(shape=>{if(shape.getAttribute("fill")===`url(#${old})`)shape.setAttribute("fill",`url(#${el.id})`)})});root.querySelectorAll('.tabs').forEach((tabs,i)=>{const prefix='tabs-'+Math.random().toString(36).slice(2,9);const panel=tabs.nextElementSibling;panel.id=prefix+'-panel';tabs.querySelectorAll('button').forEach((b,n)=>{b.id=prefix+'-'+n;b.setAttribute('aria-controls',panel.id);if(b.classList.contains('active'))panel.setAttribute('aria-labelledby',b.id)})});root.querySelectorAll('.field').forEach(f=>{const inp=f.querySelector('[aria-describedby]');if(inp){const desc=f.querySelector('.error,.hint');if(desc){desc.id='hint-'+Math.random().toString(36).slice(2,10);inp.setAttribute('aria-describedby',desc.id)}}});root.querySelectorAll('input[type=range]').forEach(r=>{r.id='range-'+Math.random().toString(36).slice(2,10);r.closest('.field')?.querySelector('output')&&(r.closest('.field').querySelector('output').htmlFor=r.id)});}
function renderGallery(){if(window.OrbitEmbed)return;const filtered=components.filter(c=>(category==='All components'||c.category===category)&&`${c.name} ${c.category} ${c.description}`.toLowerCase().includes(query.toLowerCase()));$('#section-name').innerHTML=`${category}<span id="result-count">${filtered.length}</span>`;$('#component-grid').innerHTML=filtered.map(c=>`<article class="specimen" data-component="${c.name}"><div class="specimen-head"><span>${c.name}</span><button class="inspect" data-inspect="${c.name}" aria-label="Inspect ${c.name}">${icon('code')}</button></div><div class="specimen-body">${c.html}</div><div class="specimen-footer"><span>${c.category}</span><span>${c.variants}</span></div></article>`).join('');$('#empty').hidden=filtered.length>0;prepareDemo($('#component-grid'));renderNav();OrbitMotion.prepare($('#component-grid'));OrbitNumbers.prepare($('#component-grid'))}
function setView(v,c='All components'){if(window.OrbitEmbed){window.dispatchEvent(new CustomEvent('orbit:navigate',{detail:{view:v,category:c}}));return;}view=v;category=c;const url=new URL(location.href);url.searchParams.set('view',v);url.searchParams.delete('screen');if(c!=='All components')url.searchParams.set('category',c);else url.searchParams.delete('category');history.replaceState(null,'',url);$('#gallery').hidden=v!=='gallery';$('#foundations').hidden=v!=='foundations';$('#screens').hidden=v!=='screens';$('.search').hidden=v!=='gallery';$('#crumb').textContent={gallery:'Components',foundations:'Foundations',screens:'Starter screens'}[v];$('#page-title').textContent=v==='foundations'?'The details that make it Orbit.':v==='screens'?'From small details to whole products.':'Small details. Whole products.';$('#page-description').textContent=v==='screens'?'Familiar components. Connected interactions.':v==='foundations'?'One shared language. From the smallest space to the whole screen.':'A quiet, considered kit for whatever you’re building.';if(v==='foundations')renderFoundations();else if(v==='screens')window.OrbitStarter?.showScreen('settings');else renderGallery();renderNav();OrbitMotion.panel($('#'+(v==='screens'?'screens':v==='foundations'?'foundations':'gallery')));OrbitMotion.prepare()}
const swatchNames=[['Canvas','--background'],['Surface','--bg-1'],['Subtle','--bg-2'],['Ink','--fg-4'],['Muted','--fg-3'],['Lavender','--purple-4'],['Blue','--sky-4'],['Cyan','--blue-4'],['Positive','--green-4'],['Warning','--amber-4'],['Critical','--red-4'],['Lavender wash','--purple-a1']];
function renderFoundations(){const css=getComputedStyle(document.documentElement);$('#foundations').innerHTML=`<section class="foundation-section"><h2>Color, with a light touch.</h2><p>Orbit color tokens. Click any swatch to copy its CSS token.</p><div class="swatches">${swatchNames.map(([n,t])=>`<button class="swatch" data-copy-token="${t}" style="--swatch:var(${t})"><span class="swatch-color"></span><span class="swatch-meta">${n}<small>${css.getPropertyValue(t).trim()}</small></span></button>`).join('')}</div></section><section class="foundation-section"><h2>A softer kind of type.</h2><p>OpenRunde. Rounded terminals, clear numbers, and a little personality.</p><div class="type-samples"><div><span style="font-size:40px;letter-spacing:-1.5px">Aa</span><small>Display / 40</small></div><div><span style="font-size:28px;font-weight:500">Good things ahead.</span><small>Heading / 28 medium</small></div><div><span style="font-size:14px">Room for what matters.</span><small>Body / 14 regular</small></div><div><span style="font-size:11px">A small detail</span><small>Label / 11</small></div></div></section><section class="foundation-section"><h2>Space to breathe.</h2><p>A four-pixel foundation with a generous rhythm.</p><div class="token-spaces">${[4,8,12,16,24,32,48].map((n,i)=>`<div><div class="space-bar" style="height:${n}px"></div>${n}px<small style="display:block">space-${i+1}</small></div>`).join('')}</div></section><section class="foundation-section"><h2>Soft edges. Clear purpose.</h2><p>Radii follow the shape of the component, from small status badges to pill actions.</p><div class="radius-samples"><div style="border-radius:6px">6px · Badge</div><div style="border-radius:18px">18px · Card</div><div style="border-radius:999px">Pill · Control</div></div></section><section class="foundation-section"><h2>Movement, in moderation.</h2><p>Fast feedback. Soft landings. No bounce, no continuous decoration.</p><div class="type-samples"><div>140ms<small>Hover &amp; press</small></div><div>240ms<small>Selection &amp; disclosure</small></div><div>320ms<small>Panels &amp; navigation</small></div><div>650ms<small>Data entrance</small></div></div><p style="margin-top:22px">Motion follows your device’s reduced-motion preference. Use Replay motion to revisit visible entrances. Timing and shadow tokens are included in the export.</p></section>`}
function openDetail(name){selectedComponent=components.find(c=>c.name===name);detailTab='preview';$('#detail-title').textContent=name;$('#detail-category').textContent=selectedComponent.category;$('#detail-description').textContent=selectedComponent.description;renderDetail();OrbitMotion.showDialog($('#detail-dialog'))}
function renderDetail(){document.querySelectorAll('[data-detail-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.detailTab===detailTab);b.classList.toggle('ghost',b.dataset.detailTab!==detailTab)});const el=$('#detail-content');if(detailTab==='preview'){el.innerHTML=`<div class="specimen-body">${selectedComponent.html}</div>`;el.querySelectorAll('input[type=radio]').forEach(x=>{if(!x.form)x.name='detail-'+x.name});prepareDemo(el);OrbitNumbers.prepare(el)}else{el.innerHTML='<pre></pre>';el.querySelector('pre').textContent=detailTab==='code'?selectedComponent.html:selectedComponent.tokens.map(t=>`${t}: ${getComputedStyle(document.documentElement).getPropertyValue(t).trim()};`).join('\n')}}
async function copy(text,message){try{await navigator.clipboard.writeText(text);showToast(message)}catch{showToast('Clipboard unavailable. Select and copy from the HTML tab.')}}
function closeMenus(){document.querySelectorAll('[data-menu-toggle]').forEach(b=>{b.setAttribute('aria-expanded','false');OrbitMotion.visibility(b.nextElementSibling,false)})}
function switchTab(b){const tabs=b.parentElement;tabs.querySelectorAll('button').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-selected',active);x.tabIndex=active?0:-1});const panel=tabs.nextElementSibling;panel.setAttribute('aria-labelledby',b.id);panel.innerHTML={Overview:'Everything in one place.<br>Your project is up to date and ready to go.',Activity:'Jamie joined your workspace 1 hour ago.<br>You published your project 2 minutes ago.',Settings:'Email notifications are enabled.<br>Your workspace is visible to team members.'}[b.dataset.tab]}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!e.target.closest('.dropdown'))closeMenus();if(!b)return;const d=b.dataset;if(d.themeChoice)setTheme(d.themeChoice);if(d.view)setView(d.view);if(d.category){query='';$('#search').value='';setView('gallery',d.category)}if(d.inspect)openDetail(d.inspect);if(d.detailTab){detailTab=d.detailTab;renderDetail();OrbitMotion.panel($('#detail-content'));OrbitMotion.prepare($('#detail-content'))}if(b.hasAttribute('data-close'))OrbitMotion.closeDialog(b.closest('dialog'));if(d.notify){showToast(d.notify);closeMenus()}if(b.hasAttribute('data-open-project'))OrbitMotion.showDialog($('#sample-dialog'));if(b.hasAttribute('data-copy-link'))copy(location.href,'Gallery link copied.');if(d.copyToken)copy(`var(${d.copyToken})`,'Color token copied.');if(b.hasAttribute('data-menu-toggle')){const open=b.getAttribute('aria-expanded')==='true';closeMenus();b.setAttribute('aria-expanded',!open);OrbitMotion.visibility(b.nextElementSibling,!open);if(!open)b.nextElementSibling.querySelector('button').focus()}
if(b.closest('[data-segment],[data-dock]')){b.parentElement.querySelectorAll('button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});if(b.closest('[data-dock]'))b.parentElement.nextElementSibling.textContent=b.getAttribute('aria-label')}
else if(b.classList.contains('icon-button')&&b.hasAttribute('aria-pressed'))b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');
if(b.closest('.expanded-dock')){const dock=b.closest('.expanded-dock');const expanded=b.getAttribute('aria-label')==='Realtime';dock.classList.toggle('is-expanded',expanded);dock.querySelector('[aria-label=Realtime]').setAttribute('aria-expanded',expanded);dock.querySelector('.dock-content').setAttribute('aria-hidden',!expanded);dock.querySelector('.dock-content').inert=!expanded}
if(d.toolbarAction){const demo=b.closest('.toolbar-example'),choices=[...demo.querySelectorAll('[data-toolbar-choice]:checked')];if(choices.length){showToast(`${choices.length} items ${d.toolbarAction==='copy'?'copied':'archived'} in this demo.`);if(d.toolbarAction==='archive'){choices.forEach(c=>c.checked=false);updateToolbar(demo)}}}
if(d.tab){switchTab(b);OrbitMotion.panel(b.parentElement.nextElementSibling)}
if(d.page){const p=b.closest('.pagination'),current=Number(p.querySelector('.active').dataset.page),next=d.page==='prev'?Math.max(1,current-1):d.page==='next'?Math.min(5,current+1):Number(d.page);p.querySelectorAll('button').forEach(x=>{const active=x.dataset.page===String(next);x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');if(x.dataset.page==='prev')x.disabled=next===1;if(x.dataset.page==='next')x.disabled=next===5});p.nextElementSibling.textContent=`Showing ${(next-1)*10+1}–${next*10} of 50 items`}
if(b.hasAttribute('data-step-next')){const steps=b.previousElementSibling.querySelectorAll('.step');if(b.dataset.finished){steps[1].className='step current';steps[2].className='step';delete b.dataset.finished;b.innerHTML='Continue '+icon('arrow')}else if(steps[1].classList.contains('current')){steps[1].className='step done';steps[2].className='step current';b.innerHTML='Finish '+icon('check')}else{steps[2].className='step done';b.textContent='Start again';b.dataset.finished='true';showToast('Setup complete.')}}
if(b.hasAttribute('data-remove-chip')){const chip=b.closest('.chip');b.disabled=true;const a=OrbitMotion.animate(chip,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.95)'}],120);if(a)a.finished.then(()=>chip.remove(),()=>chip.remove());else chip.remove()}const body=b.closest('.specimen-body');if(b.hasAttribute('data-clear-chips'))body.querySelector('[data-chip-list]').innerHTML='<span class="label-caption">No filters applied</span>';if(b.hasAttribute('data-reset-chips'))body.querySelector('[data-chip-list]').innerHTML=['Active','Design','This month'].map(x=>`<span class="chip">${x}<button aria-label="Remove ${x} filter" data-remove-chip>${icon('x')}</button></span>`).join('');
});
document.addEventListener('input',e=>{if(e.target.matches('input[type=range]'))e.target.closest('.field')?.querySelector('output')&&(e.target.closest('.field').querySelector('output').textContent=Number(e.target.value).toLocaleString('en-US'));if(e.target.matches('textarea'))e.target.closest('.field')?.querySelector('[data-text-count]')&&(e.target.closest('.field').querySelector('[data-text-count]').textContent=`${e.target.value.length} / 200 characters`)});
document.addEventListener('change',e=>{if(e.target.type==='file')setAttachment(e.target.closest('[data-drop-zone]'),e.target.files)});
document.addEventListener('submit',e=>{if(e.target.matches('.composer')){e.preventDefault();const inp=e.target.querySelector('input');if(!inp.value.trim())return;const el=document.createElement('div');el.className='message sent';el.textContent=inp.value.trim();const list=e.target.previousElementSibling;list.append(el);OrbitMotion.enter(el);while(list.children.length>3)list.firstElementChild.remove();inp.value=''}if(e.target.id==='project-form'){e.preventDefault();const inp=e.target.elements.project;if(!inp.value.trim()){inp.setCustomValidity('Enter a project name.');inp.reportValidity();inp.addEventListener('input',()=>inp.setCustomValidity(''),{once:true});return}OrbitMotion.closeDialog($('#sample-dialog'));showToast(`“${inp.value.trim()}” created in this demo.`);e.target.reset()}});
document.addEventListener('keydown',e=>{if(!window.OrbitEmbed&&e.key==='/'&&!e.target.closest('input,textarea,select')&&!document.querySelector('dialog[open]')){e.preventDefault();setView('gallery');$('#search').focus()}if(e.key==='Escape'){const opened=document.querySelector('[data-menu-toggle][aria-expanded=true]');if(opened){e.preventDefault();closeMenus();opened.focus()}}const group=e.target.closest('[data-segment],[data-dock],.tabs,.dropdown-panel');if(group&&['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...group.querySelectorAll('button')],index=buttons.indexOf(e.target);const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+buttons.length)%buttons.length;buttons[next].focus();if(!group.matches('.dropdown-panel'))buttons[next].click()}});
if(!window.OrbitEmbed){$('#search').addEventListener('input',e=>{query=e.target.value;renderGallery()});$('#clear-search').onclick=()=>{query='';$('#search').value='';renderGallery();$('#search').focus()};$('#copy-code').onclick=()=>copy(selectedComponent.html,'Component HTML copied.');
$('#download').onclick=async()=>{try{const response=await fetch('tokens.css');if(!response.ok)throw new Error('Token file unavailable');const blob=new Blob([await response.text()],{type:'text/css'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='orbit-tokens.css';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Light and dark tokens exported.')}catch{showToast('Could not export. Open tokens.css in the project folder.')}};
}
function updateToolbar(demo){const count=demo.querySelectorAll('[data-toolbar-choice]:checked').length;demo.querySelector('.toolbar-count').textContent=`${count} selected`;demo.querySelectorAll('[data-toolbar-action]').forEach(b=>b.disabled=!count);OrbitMotion.panel(demo.querySelector('.toolbar-count'))}
document.addEventListener('change',e=>{if(e.target.matches('[data-toolbar-choice]'))updateToolbar(e.target.closest('.toolbar-example'))});
if(!window.OrbitEmbed){$('#replay-motion').onclick=()=>OrbitMotion.replay();
const toolbarObserver=new IntersectionObserver(([entry])=>$('.gallery-toolbar').classList.toggle('is-stuck',!entry.isIntersecting),{threshold:0});toolbarObserver.observe($('.intro'));
hydrate();setTheme(document.documentElement.dataset.theme||'light');renderGallery();}
window.OrbitCatalog=components;window.OrbitPrepare=prepareDemo;window.OrbitIcon=icon;

function setAttachment(zone,files){
 if(!zone)return;const file=files?.[0];zone.classList.toggle('has-file',!!file);
 zone.querySelector('strong').textContent=file?'Asset selected':'A home for your assets';
 zone.querySelector('p').textContent=file?'Ready when you are. This file stays on your device.':'Drop a file here to get started.';
 zone.querySelector('.empty-icon').innerHTML=icon(file?'file':'folder');
 zone.querySelector('[data-select-assets]').innerHTML=icon(file?'rotate-ccw':'plus')+(file?' Replace asset':' Select assets');
 zone.querySelector('[data-remove-asset]').hidden=!file;
 OrbitMotion.feedback(zone.querySelector('[data-file-status]'),file?`${file.name} · ${file.size<1024?file.size+' B':(file.size/1024).toFixed(1)+' KB'} · selected locally`:'No assets selected');
 OrbitMotion.panel(zone.querySelector('.empty-icon'));
}
document.addEventListener('click',e=>{const zone=e.target.closest('[data-drop-zone]');if(!zone||e.target.type==='file')return;if(e.target.closest('[data-remove-asset]')){zone.querySelector('input').value='';setAttachment(zone,[]);zone.querySelector('[data-select-assets]').focus();return;}zone.querySelector('input').click()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-drop-zone]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.querySelector('input').click()}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-drop-zone]');if(zone){e.preventDefault();e.dataTransfer.dropEffect='copy';zone.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-drop-zone]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const zone=e.target.closest('[data-drop-zone]');if(!zone)return;e.preventDefault();zone.classList.remove('drag-over');if(e.dataTransfer.files.length){const input=zone.querySelector('input');input.files=e.dataTransfer.files;setAttachment(zone,input.files)}});
